CREATE TABLE tx12_stock (item_id INTEGER PRIMARY KEY, item_name TEXT NOT NULL, quantity INTEGER NOT NULL CHECK (quantity >= 0));
INSERT INTO tx12_stock VALUES (1, 'Keyboard', 8);
BEGIN;
UPDATE tx12_stock SET quantity = quantity - 3 WHERE item_id = 1;
ROLLBACK;
SELECT quantity FROM tx12_stock WHERE item_id = 1;

